import{_ as n,b as l,c as t,e as d,f as e,g as a,h as i,i as o}from"./app-02424545.js";const h={},s=e("h1",{id:"解决方案-性能优化等",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#解决方案-性能优化等","aria-hidden":"true"},"#"),a(" 解决方案(性能优化等)")],-1),c=e("h2",{id:"聊聊微前端",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#聊聊微前端","aria-hidden":"true"},"#"),a(" 聊聊微前端")],-1),p=e("p",null,"国内出品的一个微前端框架，基于 single-spa",-1),u={href:"https://zhuanlan.zhihu.com/p/78362028",target:"_blank",rel:"noopener noreferrer"},g=e("p",null,"国内技术人对于 qiankun 的解读",-1),_={href:"https://mp.weixin.qq.com/s/HgEfI8JSFOwfjG4GAoaQJQ",target:"_blank",rel:"noopener noreferrer"},f=o('<h2 id="怎么做移动端适配" tabindex="-1"><a class="header-anchor" href="#怎么做移动端适配" aria-hidden="true">#</a> 怎么做移动端适配？</h2><h4 id="viewport-方案" tabindex="-1"><a class="header-anchor" href="#viewport-方案" aria-hidden="true">#</a> viewport 方案:</h4><p>viewport 方案即是使用 vw/vh 作为样式单位。vw、vh 将 viewport 分成了一百等份，1vw 等于视口 1%的宽度，1vh 等于视口 1%的高度。当我们的设计稿是 750px 时，1vw 就等于 7.5px。还是用之前那个例子，750px 设计稿下，divA 的宽度为 50px，使用 vw 作为样式单位，divA 的宽度是多少 vw 呢？还是将 divA 的宽度设置 x vw，代入 x:50 = 1:7.5，得到 x≈6.67vw。</p><h4 id="rem-方案" tabindex="-1"><a class="header-anchor" href="#rem-方案" aria-hidden="true">#</a> rem 方案:</h4><p>rem 是一个相对于页面根元素 html 的 font-size 的一个单位，举个例子，假如设置了根元素 html 的 font-size 为 18px，那么，1rem 等于 18px。由此可知，rem 的大小是会随着根元素 html 的 font-size 的改变而改变的。rem 方案就是利用了这一点，根据不同的屏幕尺寸，来设置不同的根元素 html 的 font-size 的大小，以此来达到适配不同屏幕尺寸的目的。</p>',5),b={href:"https://github.com/amfe/article/issues/17",target:"_blank",rel:"noopener noreferrer"},x=o('<h2 id="ios-与安卓兼容问题" tabindex="-1"><a class="header-anchor" href="#ios-与安卓兼容问题" aria-hidden="true">#</a> IOS 与安卓兼容问题</h2><p>当开发移动应用时，iOS 和 Android 平台之间存在一些兼容性问题需要注意：</p><h4 id="_1px-问题" tabindex="-1"><a class="header-anchor" href="#_1px-问题" aria-hidden="true">#</a> 1px 问题：</h4><p>css 像素与物理像素的差异导致，在高密度屏幕上（如 Retina 屏幕），1 像素的线可能看起来过于粗，影响视觉效果。解决方法包括：</p><ul><li>使用伪类元素 <code>::after</code> 或 <code>::before</code> 来创建半透明边框，从而模拟出 1px 的效果。</li><li>使用媒体查询来计算设备像素比（devicePixelRatio），并设置相应的样式 transform 动态缩放。</li></ul><h4 id="iphone-x-底部兼容问题" tabindex="-1"><a class="header-anchor" href="#iphone-x-底部兼容问题" aria-hidden="true">#</a> iPhone X 底部兼容问题：</h4><p>iPhone X 及以上机型采用了刘海屏设计，因此底部存在一个 &quot;安全区域&quot;，需要特别处理以确保内容不被遮挡。解决方法包括：</p><ul><li>使用 CSS 的 <code>safe-area-inset-*</code> 相关属性来调整布局，确保内容不被刘海或底部安全区域遮挡。</li><li>在 iOS 上使用 JavaScript 获取安全区域信息，然后动态调整页面布局。</li></ul><h4 id="时间格式问题" tabindex="-1"><a class="header-anchor" href="#时间格式问题" aria-hidden="true">#</a> 时间格式问题：</h4><p>iOS 和 Android 在处理日期和时间格式上可能存在差异，因此需要注意格式化和解析时间数据时的兼容性。解决方法包括：</p><ul><li>使用标准的日期和时间格式（如 ISO 8601）来存储和传递时间数据。</li><li>在客户端和服务器端进行统一的时间格式化和解析处理，避免因不同平台而引起的问题。</li><li>在开发过程中进行充分的测试，确保在不同平台上时间的显示和处理都是正确的。</li></ul><p>通过考虑并解决这些兼容性问题，可以确保移动应用在 iOS 和 Android 平台上都能够有良好的用户体验。</p><h2 id="虚拟列表" tabindex="-1"><a class="header-anchor" href="#虚拟列表" aria-hidden="true">#</a> 虚拟列表</h2><p>其实现在一些表格组件已经集成该功能，比如 vxe-table 库</p>',14),m={href:"https://juejin.cn/post/6844903982742110216",target:"_blank",rel:"noopener noreferrer"},S=o('<h2 id="提升页面加载速度" tabindex="-1"><a class="header-anchor" href="#提升页面加载速度" aria-hidden="true">#</a> 提升页面加载速度</h2><ul><li>减少 HTTP 请求： 页面加载的主要消耗是网络请求时间，因此减少页面的 HTTP 请求是提升加载速度的有效途径。可以通过合并和压缩 CSS、JavaScript 文件，使用雪碧图来减少图片请求等方式来降低 HTTP 请求数量。</li><li>使用浏览器缓存： 利用浏览器缓存可以减少重复加载相同资源的时间。合理设置缓存头，对静态资源使用长时间缓存，对动态资源使用适当的缓存控制，可以有效减少服务器负担和提高页面加载速度。</li><li>优化图片： 图片通常是页面中占用带宽较大的资源。使用适当的图片格式、压缩图片以减小文件大小、懒加载技术等都是优化图片加载的手段。</li><li>使用异步加载： 将不影响首屏展示的资源使用异步加载方式加载，可以提高页面的初始加载速度。这包括将非关键的 JavaScript 延迟加载，使用 async 或 defer 属性。</li><li>代码优化： 优化 JavaScript 和 CSS 代码，删除冗余、未使用的代码，减小文件大小。可以使用代码压缩工具，如 UglifyJS（JavaScript）和 cssnano（CSS）。</li><li>使用 CDN： 将静态资源部署到 CDN（内容分发网络）上，可以加速资源的加载速度，减轻服务器负担，并提高全球范围内用户的访问速度。</li><li>延迟加载非关键资源： 将页面上非必要资源的加载推迟到页面加载完成后再进行，例如延迟加载图片、延迟加载某些模块的内容。</li><li>减少重绘和回流： 避免频繁的 DOM 操作，减少页面的重绘（Repaint）和回流（Reflow）次数。合理使用 CSS 合并、动画优化等技术。</li><li>使用服务端渲染（SSR）： 对于单页面应用，考虑使用服务端渲染，可以提前生成好 HTML，在客户端只需要执行 JavaScript 以达到更快的首屏加载速度。</li><li>分析工具和监测： 使用工具如 Google PageSpeed Insights、Lighthouse 等进行性能分析，定期监测和分析网站性能，找到潜在的性能问题并及时优化。</li><li>开放性问题.....</li></ul><h2 id="关于-seo" tabindex="-1"><a class="header-anchor" href="#关于-seo" aria-hidden="true">#</a> 关于 SEO</h2>',3),v={href:"https://blog.csdn.net/weixin_45899230/article/details/107512596",target:"_blank",rel:"noopener noreferrer"},k=o('<h2 id="关于图片优化" tabindex="-1"><a class="header-anchor" href="#关于图片优化" aria-hidden="true">#</a> 关于图片优化</h2><ul><li>懒加载</li><li>第三方压缩裁剪(裁剪的原理是什么)</li><li>cdn 加速</li><li>规范组件化使用，可以考虑使用 eslint 检查</li></ul><h2 id="结合实际说说-webpack-调优" tabindex="-1"><a class="header-anchor" href="#结合实际说说-webpack-调优" aria-hidden="true">#</a> 结合实际说说 webpack 调优</h2><h3 id="_1-减少打包体积" tabindex="-1"><a class="header-anchor" href="#_1-减少打包体积" aria-hidden="true">#</a> 1. 减少打包体积</h3><ul><li><strong>代码分割</strong>：使用 <code>SplitChunksPlugin</code> 插件，将代码拆分成更小的块，以便更好地利用浏览器缓存。</li><li><strong>Tree Shaking</strong>：确保使用 ES6 模块语法，启用 <code>mode: &#39;production&#39;</code>，移除未使用的代码。</li><li><strong>压缩代码</strong>：使用 <code>TerserPlugin</code> 压缩 JavaScript，使用 <code>cssnano</code> 压缩 CSS。</li><li><strong>图片优化</strong>：使用 <code>image-webpack-loader</code> 对图片进行压缩和优化。</li></ul><h3 id="_2-提升打包速度" tabindex="-1"><a class="header-anchor" href="#_2-提升打包速度" aria-hidden="true">#</a> 2. 提升打包速度</h3><ul><li><strong>多线程/多进程构建</strong>：使用 <code>thread-loader</code> 和 <code>parallel-webpack</code> 等插件，利用多核 CPU 提升构建速度。</li><li><strong>缓存</strong>：使用 <code>cache-loader</code> 或者 <code>hard-source-webpack-plugin</code> 缓存构建结果，减少重复构建时间。</li><li><strong>缩小构建范围</strong>：通过 <code>include</code> 和 <code>exclude</code> 选项限制 <code>loader</code> 的处理范围，减少不必要的文件处理。</li></ul><h3 id="_3-优化开发体验" tabindex="-1"><a class="header-anchor" href="#_3-优化开发体验" aria-hidden="true">#</a> 3. 优化开发体验</h3><ul><li><strong>热模块替换（HMR）</strong>：使用 <code>HotModuleReplacementPlugin</code> 实现模块热替换，提升开发效率。</li><li><strong>快速重建</strong>：使用 <code>webpack-dev-server</code> 提供快速的开发服务器，支持实时重载和模块热替换。</li><li><strong>Source Maps</strong>：在开发模式下启用 <code>source-map</code>，方便调试代码。</li></ul><h3 id="_4-其他优化" tabindex="-1"><a class="header-anchor" href="#_4-其他优化" aria-hidden="true">#</a> 4. 其他优化</h3><ul><li><strong>DLLPlugin</strong>：使用 <code>DLLPlugin</code> 和 <code>DLLReferencePlugin</code> 预编译第三方库，减少构建时间。</li><li><strong>按需加载</strong>：使用 <code>import()</code> 动态引入模块，实现按需加载，减少初始加载时间。</li><li><strong>分析工具</strong>：使用 <code>webpack-bundle-analyzer</code> 分析打包结果，找出体积较大的模块进行优化。</li></ul><p>通过以上方法，可以有效提升 webpack 的打包性能和开发体验。</p><h2 id="性能分析工具的使用" tabindex="-1"><a class="header-anchor" href="#性能分析工具的使用" aria-hidden="true">#</a> 性能分析工具的使用</h2>',13),w={href:"https://developer.chrome.com/docs/devtools/performance/reference?hl=zh-cn#memory",target:"_blank",rel:"noopener noreferrer"},C=o('<h2 id="什么是-rbac-基于角色的访问控制" tabindex="-1"><a class="header-anchor" href="#什么是-rbac-基于角色的访问控制" aria-hidden="true">#</a> 什么是 RBAC（基于角色的访问控制）</h2><p>RBAC（Role-Based Access Control，基于角色的访问控制）是一种常见的权限管理模型。它通过将权限与角色关联，再将角色分配给用户，从而实现对系统资源的访问控制。RBAC 的核心思想是“用户-角色-权限”三者之间的关系：</p><ul><li><strong>用户（User）</strong>：系统的使用者。</li><li><strong>角色（Role）</strong>：一组权限的集合，代表某类用户的职责或职位。</li><li><strong>权限（Permission）</strong>：对系统资源的操作授权，如读、写、删除等。</li></ul><h3 id="rbac-的优势" tabindex="-1"><a class="header-anchor" href="#rbac-的优势" aria-hidden="true">#</a> RBAC 的优势</h3><ul><li><strong>简化权限管理</strong>：只需管理角色与权限的关系，用户只需分配角色即可获得相应权限。</li><li><strong>灵活扩展</strong>：新增用户或权限时，只需调整角色分配，无需逐一修改用户权限。</li><li><strong>安全合规</strong>：便于实现最小权限原则，减少权限滥用风险。</li></ul><h3 id="rbac-的常见实现" tabindex="-1"><a class="header-anchor" href="#rbac-的常见实现" aria-hidden="true">#</a> RBAC 的常见实现</h3><ol><li><strong>定义角色</strong>：如管理员、编辑、访客等。</li><li><strong>分配权限</strong>：为每个角色分配相应的操作权限。</li><li><strong>分配角色</strong>：将角色分配给具体用户。</li></ol><p>RBAC 广泛应用于企业信息系统、后台管理系统等场景，是权限设计的主流方案之一。</p>',8);function R(P,A){const r=l("ExternalLinkIcon");return t(),d("div",null,[s,c,p,e("blockquote",null,[e("p",null,[e("a",u,[a("可能是你见过最完善的微前端解决方案"),i(r)])])]),g,e("blockquote",null,[e("p",null,[e("a",_,[a("微前端方案 qiankun 只是更完善的 single-spa"),i(r)])])]),f,e("blockquote",null,[e("p",null,[e("a",b,[a("使用 Flexible 实现手淘 H5 页面的终端适配"),i(r)])])]),x,e("blockquote",null,[e("p",null,[e("a",m,[a("「前端进阶」高性能渲染十万条数据(虚拟列表) - 掘金"),i(r)])])]),S,e("blockquote",null,[e("p",null,[e("a",v,[a("前端搜索引擎优化（SEO）_如故~的博客-CSDN 博客"),i(r)])])]),k,e("blockquote",null,[e("p",null,[e("a",w,[a("谷歌浏览器 performance 面板使用"),i(r)])])]),C])}const O=n(h,[["render",R],["__file","h-optimization.html.vue"]]);export{O as default};
